const items = $input.all();
const responseData = items[0].json.body || items[0].json;
let mentions = [];
if (Array.isArray(responseData)) {
  mentions = responseData;
} else if (responseData.results) {
  mentions = responseData.results;
} else if (responseData.data) {
  mentions = responseData.data;
}
const mentionTexts = mentions.slice(0, 20).map((m, i) => `[${i+1}] Source: ${m.source || 'unknown'} | Text: ${m.text || m.content || JSON.stringify(m).substring(0, 200)}`).join('\n');
return [{ json: { mentionTexts, mentionCount: mentions.length, rawMentions: mentions.slice(0, 20) } }];

const items = $input.all();
const aiResponse = items[0].json.message.content;
let parsed;
try {
  parsed = JSON.parse(aiResponse);
} catch(e) {
  parsed = { distribution: {}, urgency: false, overall_summary: aiResponse };
}
return [{
  json: {
    date: new Date().toISOString(),
    positivePercent: parsed.distribution?.positive || 0,
    negativePercent: parsed.distribution?.negative || 0,
    neutralPercent: parsed.distribution?.neutral || 0,
    positiveThemes: Array.isArray(parsed.positive_themes) ? parsed.positive_themes.join(', ') : '',
    negativeThemes: Array.isArray(parsed.negative_themes) ? parsed.negative_themes.join(', ') : '',
    urgency: parsed.urgency || false,
    overallSummary: parsed.overall_summary || '',
    mentionCount: items[0].json.mentionCount || 0
  }
}];

